for name in CHANGES:
    base = subprocess.check_output(['git', 'show', '2fa80a404518e59db5d6157b50a7521aa9c1512f:' + name])
    if base != Path(name).read_bytes():
        raise SystemExit('Refusing changed integration base: ' + name)
for name, edits in CHANGES.items():
    p = Path(name)
    lines = p.read_text().splitlines(keepends=True)
    for start, end, text in reversed(edits):
        lines[start:end] = [text]
    p.write_text(''.join(lines))
